function eightWayPath(grid: number[][]): number {
  const n = grid.length;
  if (grid[0][0] || grid[n - 1][n - 1]) return -1;
  const seen = grid.map(row => row.slice()); // 1 = blocked or already queued
  const queue: number[][] = [[0, 0, 1]];
  seen[0][0] = 1;
  for (let head = 0; head < queue.length; head++) {
    const [i, j, d] = queue[head];
    if (i === n - 1 && j === n - 1) return d;
    for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
      const x = i + di, y = j + dj;
      if (x < 0 || y < 0 || x >= n || y >= n || seen[x][y]) continue;
      seen[x][y] = 1; // mark on push, so each cell is queued once
      queue.push([x, y, d + 1]);
    }
  }
  return -1;
}

